W=H=15
g=[[0]*W for _ in range(H)]
bars=[(2,2,[(0,2),(4,5)]),(3,5,[(6,14)]),(6,3,[(0,2),(4,6)]),(8,9,[(6,14)]),(11,4,[(0,7),(9,14)])]
# place bars
for r,c,segs in bars:
    for a,b in segs:
        for c2 in range(a,b+1): g[r][c2]=c
# gap columns per bar
gapcols={2:[3],3:[6],6:[3],8:[6],11:[3,8]}
# vertical markers: color, col, rows
verts=[(6,3,13,14),(8,8,14,14)]
for c,col,r1,r2 in verts:
    for r in range(r1,r2+1): g[r][c]=col
# fill gaps and extend upward from each bar row in its gap cols, stop at colored
for r,c,segs in bars:
    for gc in gapcols[r]:
        g[r][gc]=c
        rr=r-1
        while rr>=0 and g[rr][gc]==0:
            g[rr][gc]=c; rr-=1
# vertical markers extend upward
for c,col,r1,r2 in verts:
    rr=r1-1
    while rr>=0 and g[rr][c]==0:
        g[rr][c]=col; rr-=1
for row in g: print(row)
assert all(len(r)==15 for r in g) and len(g)==15
import json; print(json.dumps(g))

